async function createExamination(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const id=input.id||newId('exam');const now=iso(new Date());await conn.query('INSERT INTO examinations (id,tenant_id,school_id,class_id,academic_config_id,examination_type_id,name,status,publication_status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.classId,input.academicConfigId,input.examinationTypeId,input.name,input.status||'DRAFT','UNPUBLISHED',actorId||null,now,now]);for(const c of input.components||[])await conn.query('INSERT INTO examination_components (id,examination_id,subject_id,name,maximum_score,position_no) VALUES (?,?,?,?,?,?)',[newId('component'),id,c.subjectId,c.name,c.maximumScore,c.positionNo||1]);await conn.commit();return (await academicRows('SELECT * FROM examinations WHERE id=?',[id]))[0];}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
