async function createScore(input,actorId){await ensureInitialized();const id=input.id||newId('score');const now=iso(new Date());await getPool().query('INSERT INTO scores (id,tenant_id,school_id,class_id,student_id,subject_id,examination_id,component_id,raw_score,maximum_score,status,entered_by,entered_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.classId,input.studentId,input.subjectId,input.examinationId,input.componentId,input.rawScore,input.maximumScore,input.status||'DRAFT',actorId||null,now,now]);return (await academicRows('SELECT * FROM scores WHERE id=?',[id]))[0];}
