async function createBulkScores(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();const accepted=[],rejected=[];try{await conn.beginTransaction();for(let i=0;i<(input.rows||[]).length;i++){const row=input.rows[i];try{const raw=Number(row.rawScore);if(!Number.isFinite(raw)||raw<0)throw Object.assign(new Error('Score must be between zero and maximum score'),{code:'DOMAIN_VALIDATION'});const [refs]=await conn.query('SELECT s.id AS student_id,s.class_id,s.school_id,s.tenant_id,c.id AS component_id,c.subject_id,c.maximum_score,e.id AS examination_id,e.class_id AS examination_class,e.school_id AS examination_school,e.tenant_id AS examination_tenant FROM students s JOIN examinations e ON e.id=? JOIN examination_components c ON c.id=? AND c.examination_id=e.id WHERE s.id=? AND s.tenant_id=? AND s.school_id=? AND s.class_id=? AND e.tenant_id=? AND e.school_id=? AND e.class_id=?',[row.examinationId,row.componentId,row.studentId,input.tenantId,input.schoolId,input.classId,input.tenantId,input.schoolId,input.classId]);if(!refs.length||String(refs[0].subject_id)!==String(row.subjectId))throw Object.assign(new Error('Student, examination, subject, and component must belong to the same class and school'),{code:'DOMAIN_VALIDATION'});const max=Number(refs[0].maximum_score);if(!Number.isFinite(max)||raw>max)throw Object.assign(new Error('Score must be between zero and maximum score'),{code:'DOMAIN_VALIDATION'});const id=row.id||newId('score');const now=iso(new Date());await conn.query('INSERT INTO scores (id,tenant_id,school_id,class_id,student_id,subject_id,examination_id,component_id,raw_score,maximum_score,status,entered_by,entered_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE raw_score=VALUES(raw_score),maximum_score=VALUES(maximum_score),status=VALUES(status),entered_by=VALUES(entered_by),updated_at=VALUES(updated_at)',[id,input.tenantId,input.schoolId,input.classId,row.studentId,row.subjectId,row.examinationId,row.componentId,raw,max,row.status||'DRAFT',actorId||null,now,now]);accepted.push({index:i,studentId:row.studentId,componentId:row.componentId});}catch(e){rejected.push({index:i,reason:e.message||'Score rejected'});}}if(rejected.length)throw Object.assign(new Error('One or more scores were rejected'),{code:'DOMAIN_VALIDATION',details:{accepted,rejected}});await conn.commit();const ids=(input.rows||[]).map(x=>x.studentId);return await academicRows('SELECT * FROM scores WHERE tenant_id=? AND school_id=? AND class_id=? AND student_id IN ('+ids.map(()=>'?').join(',')+')',[input.tenantId,input.schoolId,input.classId,...ids]);}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function createMockScoresBulk(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const ids=[];for(const item of input.records||[]){const raw=Number(item.rawScore);const mockId=item.mockExaminationId||input.mockExaminationId;if(!mockId)throw Object.assign(new Error('Mock examination is required'),{code:'DOMAIN_VALIDATION'});if(!Number.isFinite(raw)||raw<0)throw Object.assign(new Error('Mock score must be between zero and maximum score'),{code:'DOMAIN_VALIDATION'});const [refs]=await conn.query('SELECT m.tenant_id,m.school_id,m.class_id,mc.id AS component_id,mc.maximum_score FROM mock_examinations m JOIN mock_components mc ON mc.id=? AND mc.mock_examination_id=m.id JOIN students s ON s.id=? AND s.tenant_id=m.tenant_id AND s.school_id=m.school_id AND s.class_id=m.class_id WHERE m.id=? AND m.tenant_id=? AND m.school_id=? AND m.class_id=?',[item.componentId,item.studentId,mockId,input.tenantId,input.schoolId,input.classId]);if(!refs.length)throw Object.assign(new Error('Mock student and component must belong to the same class and school'),{code:'DOMAIN_VALIDATION'});const max=Number(refs[0].maximum_score);if(raw>max)throw Object.assign(new Error('Mock score must be between zero and maximum score'),{code:'DOMAIN_VALIDATION'});const id=item.id||newId('mockscore');const now=iso(new Date());await conn.query('INSERT INTO mock_scores (id,mock_examination_id,component_id,student_id,raw_score,maximum_score,entered_by,entered_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE raw_score=VALUES(raw_score),maximum_score=VALUES(maximum_score),entered_by=VALUES(entered_by),updated_at=VALUES(updated_at)',[id,mockId,item.componentId,item.studentId,raw,max,actorId||null,now,now]);ids.push(id);}await conn.commit();return await academicRows('SELECT * FROM mock_scores WHERE id IN ('+ids.map(()=>'?').join(',')+') ORDER BY updated_at DESC',ids);}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function createMockScore(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const raw=Number(input.rawScore);if(!Number.isFinite(raw)||raw<0)throw Object.assign(new Error('Mock score must be between zero and maximum score'),{code:'DOMAIN_VALIDATION'});const [refs]=await conn.query('SELECT m.tenant_id,m.school_id,m.class_id,mc.id AS component_id,mc.maximum_score FROM mock_examinations m JOIN mock_components mc ON mc.id=? AND mc.mock_examination_id=m.id JOIN students s ON s.id=? AND s.tenant_id=m.tenant_id AND s.school_id=m.school_id AND s.class_id=m.class_id WHERE m.id=? AND m.tenant_id=? AND m.school_id=? AND m.class_id=?',[input.componentId,input.studentId,input.mockExaminationId,input.tenantId,input.schoolId,input.classId]);if(!refs.length)throw Object.assign(new Error('Mock student and component must belong to the same class and school'),{code:'DOMAIN_VALIDATION'});const max=Number(refs[0].maximum_score);if(raw>max)throw Object.assign(new Error('Mock score must be between zero and maximum score'),{code:'DOMAIN_VALIDATION'});const id=input.id||newId('mockscore');const now=iso(new Date());await conn.query('INSERT INTO mock_scores (id,mock_examination_id,component_id,student_id,raw_score,maximum_score,entered_by,entered_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE raw_score=VALUES(raw_score),maximum_score=VALUES(maximum_score),entered_by=VALUES(entered_by),updated_at=VALUES(updated_at)',[id,input.mockExaminationId,input.componentId,input.studentId,raw,max,actorId||null,now,now]);await conn.commit();return (await academicRows('SELECT * FROM mock_scores WHERE mock_examination_id=? AND component_id=? AND student_id=?',[input.mockExaminationId,input.componentId,input.studentId]))[0];}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function calculateResult(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const refs=await conn.query('SELECT s.id FROM students s JOIN examinations e ON e.id=? AND e.tenant_id=? AND e.school_id=? AND e.class_id=? JOIN academic_configurations ac ON ac.id=? AND ac.tenant_id=? AND ac.school_id=? WHERE s.id=? AND s.tenant_id=? AND s.school_id=? AND s.class_id=?',[input.examinationId,input.tenantId,input.schoolId,input.classId,input.academicConfigId,input.tenantId,input.schoolId,input.studentId,input.tenantId,input.schoolId,input.classId]);if(!refs[0].length)throw Object.assign(new Error('Student, examination, class, and academic configuration must belong to the same school and tenant'),{code:'DOMAIN_VALIDATION'});const scoreRows=await conn.query('SELECT raw_score,maximum_score,subject_id,component_id FROM scores WHERE tenant_id=? AND school_id=? AND class_id=? AND student_id=? AND examination_id=? ORDER BY subject_id,component_id',[input.tenantId,input.schoolId,input.classId,input.studentId,input.examinationId]);const rows=scoreRows[0],total=rows.reduce((n,x)=>n+Number(x.raw_score),0),max=rows.reduce((n,x)=>n+Number(x.maximum_score),0),payload={scoreCount:rows.length,total,max,percentage:max?Number((total/max*100).toFixed(2)):0,subjects:rows},existingRows=await conn.query('SELECT id FROM published_results WHERE tenant_id=? AND school_id=? AND class_id=? AND student_id=? AND academic_config_id=? AND examination_id=? ORDER BY version_no DESC LIMIT 1 FOR UPDATE',[input.tenantId,input.schoolId,input.classId,input.studentId,input.academicConfigId,input.examinationId]),now=iso(new Date());let resultId;if(existingRows[0].length){resultId=existingRows[0][0].id;await conn.query("UPDATE published_results SET result_json=?,publication_status='CALCULATED',published_by=NULL,published_at=NULL,updated_at=? WHERE id=?",[JSON.stringify(payload),now,resultId]);}else{resultId=input.id||newId('result');await conn.query('INSERT INTO published_results (id,tenant_id,school_id,class_id,student_id,academic_config_id,examination_id,version_no,result_json,publication_status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[resultId,input.tenantId,input.schoolId,input.classId,input.studentId,input.academicConfigId,input.examinationId,1,JSON.stringify(payload),'CALCULATED',now,now]);}await conn.commit();return (await academicRows('SELECT * FROM published_results WHERE id=?',[resultId]))[0];}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function updateResultRemarks(resultId,remarks,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const [rows]=await conn.query("SELECT * FROM published_results WHERE id=? AND publication_status='PUBLISHED' FOR UPDATE",[resultId]);if(!rows.length)throw Object.assign(new Error('Published result was not found'),{code:'DOMAIN_VALIDATION'});const current=parseJson(rows[0].result_json,{});const next=Object.assign({},current,{remarks});await conn.query('UPDATE published_results SET result_json=?,updated_at=? WHERE id=?',[JSON.stringify(next),iso(new Date()),resultId]);await conn.commit();return (await academicRows('SELECT * FROM published_results WHERE id=?',[resultId]))[0];}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
