async function saveTeacherAttendance(input,actorId,actorRole){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const dates=[];for(const item of input.records||[]){const [staffRows]=await conn.query('SELECT id,status,user_id FROM staff WHERE tenant_id=? AND school_id=? AND (id=? OR staff_identifier=?) LIMIT 1',[input.tenantId,input.schoolId,item.staffId,item.staffId]);const staff=staffRows[0];if(!staff||String(staff.status).toUpperCase()!=='ACTIVE')throw Object.assign(new Error('Staff reference is invalid or inactive for this school'),{code:'DOMAIN_VALIDATION'});if(actorRole==='TEACHER'&&String(staff.user_id)!==String(actorId))throw Object.assign(new Error('Teachers may only update their own attendance'),{code:'AUTHORIZATION_DENIED'});const id=newId('teacher-att');const now=iso(new Date());await conn.query('INSERT INTO teacher_attendance_records (id,tenant_id,school_id,staff_id,attendance_date,status,sign_in,sign_out,note,recorded_by,recorded_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=COALESCE(VALUES(status),status),sign_in=COALESCE(VALUES(sign_in),sign_in),sign_out=COALESCE(VALUES(sign_out),sign_out),note=VALUES(note),recorded_by=VALUES(recorded_by),updated_at=VALUES(updated_at)',[id,input.tenantId,input.schoolId,staff.id,item.attendanceDate,item.status===undefined?null:String(item.status).toUpperCase(),item.signIn||null,item.signOut||null,item.note||null,actorId,now,now]);dates.push(item.attendanceDate);}await conn.commit();const marks=dates.map(()=>'?').join(',');return await academicRows('SELECT * FROM teacher_attendance_records WHERE tenant_id=? AND school_id=? AND attendance_date IN ('+marks+') ORDER BY attendance_date DESC',[input.tenantId,input.schoolId,...dates]);}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function createPromotionsBulk(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const ids=[];for(const item of input.records||[]){if(item.sourceClassId===item.destinationClassId)throw Object.assign(new Error('Source and destination classes must differ'),{code:'DOMAIN_VALIDATION'});const [refs]=await conn.query('SELECT s.id FROM students s JOIN classes src ON src.id=? AND src.tenant_id=? AND src.school_id=? JOIN classes dst ON dst.id=? AND dst.tenant_id=? AND dst.school_id=? JOIN academic_configurations ac ON ac.id=? AND ac.tenant_id=? AND ac.school_id=? WHERE s.id=? AND s.tenant_id=? AND s.school_id=? AND s.class_id=?',[item.sourceClassId,input.tenantId,input.schoolId,item.destinationClassId,input.tenantId,input.schoolId,item.academicConfigId,input.tenantId,input.schoolId,item.studentId,input.tenantId,input.schoolId,item.sourceClassId]);if(!refs.length)throw Object.assign(new Error('Student, classes, and academic configuration must belong to the same school and tenant'),{code:'DOMAIN_VALIDATION'});const id=item.id||newId('promotion'),now=iso(new Date());await conn.query('INSERT INTO promotion_records (id,tenant_id,school_id,student_id,source_class_id,destination_class_id,academic_config_id,decision,status,decided_by,decided_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,item.studentId,item.sourceClassId,item.destinationClassId,item.academicConfigId,item.decision||'PROMOTE',item.status||'DRAFT',actorId,item.status==='APPROVED'?now:null,now,now]);ids.push(id);}await conn.commit();return await academicRows('SELECT * FROM promotion_records WHERE id IN ('+ids.map(()=>'?').join(',')+') ORDER BY created_at DESC',ids);}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function createPromotion(input,actorId){await ensureInitialized();const id=input.id||newId('promotion');const now=iso(new Date());await getPool().query('INSERT INTO promotion_records (id,tenant_id,school_id,student_id,source_class_id,destination_class_id,academic_config_id,decision,status,decided_by,decided_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.studentId,input.sourceClassId,input.destinationClassId,input.academicConfigId,input.decision||'PROMOTE',input.status||'DRAFT',actorId||null,input.status==='APPROVED'?now:null,now,now]);return (await academicRows('SELECT * FROM promotion_records WHERE id=?',[id]))[0];}
async function createMockExamination(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const id=input.id||newId('mock');const now=iso(new Date());await conn.query('INSERT INTO mock_examinations (id,tenant_id,school_id,class_id,academic_config_id,label,format_code,status,publication_status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.classId,input.academicConfigId,input.label,input.formatCode||'B',input.status||'DRAFT','UNPUBLISHED',actorId||null,now,now]);for(const c of input.components||[])await conn.query('INSERT INTO mock_components (id,mock_examination_id,subject_id,name,maximum_score) VALUES (?,?,?,?,?)',[newId('mockcomp'),id,c.subjectId,c.name,c.maximumScore]);await conn.commit();return (await academicRows('SELECT * FROM mock_examinations WHERE id=?',[id]))[0];}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
