async function tableCounts() { await ensureInitialized(); const out = {}; for (const table of ['users','credentials','roles','permissions','user_roles','tenants','tenant_memberships','regions','districts','schools','staff','students','classes','parent_student_relationships','staff_school_assignments','teacher_class_assignments','server_sessions','audit_events','payment_intents','payment_transactions','subscriptions','payment_events','password_reset_records','file_records','schema_migrations']) { const [rows] = await getPool().query(`SELECT COUNT(*) AS count FROM ${table}`); out[table] = Number(rows[0].count); } return out; }
async function close() { if (pool) { await pool.end(); pool = null; initialized = null; } }

async function rotateQrIdentity(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const type=String(input.entityType||'').toUpperCase();if(!['STUDENT','STAFF'].includes(type))throw Object.assign(new Error('Invalid QR entity type'),{code:'DOMAIN_VALIDATION'});const table=type==='STUDENT'?'students':'staff';const [rows]=await conn.query(`SELECT id,tenant_id,school_id,full_name,status FROM ${table} WHERE id=? LIMIT 1`,[input.entityId]);const entity=rows[0];if(!entity||String(entity.status).toUpperCase()!=='ACTIVE')throw Object.assign(new Error('Active record not found'),{code:'DOMAIN_VALIDATION'});await conn.query('UPDATE qr_attendance_identities SET active=FALSE,revoked_at=CURRENT_TIMESTAMP WHERE entity_type=? AND entity_id=? AND active=TRUE',[type,entity.id]);const id=newId('qr');const raw=`ETQR1.${id}.${crypto.randomBytes(24).toString('base64url')}`;const hash=crypto.createHash('sha256').update(raw).digest('hex');const now=iso(new Date());await conn.query('INSERT INTO qr_attendance_identities (id,tenant_id,school_id,entity_type,entity_id,token_hash,token_suffix,active,issued_at,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)',[id,entity.tenant_id,entity.school_id,type,entity.id,hash,raw.slice(-8),true,now,actorId||null]);await conn.commit();return {id,token:raw,entityType:type,entityId:entity.id,tenantId:entity.tenant_id,schoolId:entity.school_id,fullName:entity.full_name,issuedAt:now};}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function resolveQrIdentity(token){await ensureInitialized();const hash=crypto.createHash('sha256').update(String(token||'')).digest('hex');const [rows]=await getPool().query(`SELECT q.*,CASE WHEN q.entity_type='STUDENT' THEN s.full_name ELSE st.full_name END AS full_name,CASE WHEN q.entity_type='STUDENT' THEN s.status ELSE st.status END AS entity_status, s.class_id FROM qr_attendance_identities q LEFT JOIN students s ON q.entity_type='STUDENT' AND s.id=q.entity_id LEFT JOIN staff st ON q.entity_type='STAFF' AND st.id=q.entity_id WHERE q.token_hash=? AND q.active=TRUE LIMIT 1`,[hash]);return rows[0]||null;}
async function recordQrAttendance(input,actorId,metadata={}){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const hash=crypto.createHash('sha256').update(String(input.token||'')).digest('hex');const [rows]=await conn.query(`SELECT q.*,CASE WHEN q.entity_type='STUDENT' THEN s.full_name ELSE st.full_name END AS full_name,CASE WHEN q.entity_type='STUDENT' THEN s.status ELSE st.status END AS entity_status,s.class_id FROM qr_attendance_identities q LEFT JOIN students s ON q.entity_type='STUDENT' AND s.id=q.entity_id LEFT JOIN staff st ON q.entity_type='STAFF' AND st.id=q.entity_id WHERE q.token_hash=? AND q.active=TRUE LIMIT 1`,[hash]);const identity=rows[0];if(!identity||String(identity.entity_status).toUpperCase()!=='ACTIVE')throw Object.assign(new Error('QR code is invalid, disabled, or expired'),{code:'QR_INVALID'});if(String(identity.school_id)!==String(input.schoolId))throw Object.assign(new Error('QR code belongs to another school'),{code:'AUTHORIZATION_DENIED'});const date=input.attendanceDate||new Date().toISOString().slice(0,10);const now=iso(new Date());const [prior]=await conn.query('SELECT id FROM qr_attendance_events WHERE entity_type=? AND entity_id=? AND attendance_date=? LIMIT 1',[identity.entity_type,identity.entity_id,date]);if(prior.length){await conn.query('INSERT INTO qr_attendance_events (id,identity_id,tenant_id,school_id,entity_type,entity_id,attendance_date,scan_timestamp,attendance_method,sync_status,scan_result,scanned_by,user_agent,metadata_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[newId('qrevent'),identity.id,identity.tenant_id,identity.school_id,identity.entity_type,identity.entity_id,date,now,'QR','SYNCHRONIZED','DUPLICATE',actorId||null,metadata.userAgent||null,json({duplicateOf:prior[0].id})]);await conn.commit();return {duplicate:true,identity:{entityType:identity.entity_type,entityId:identity.entity_id,schoolId:identity.school_id,fullName:identity.full_name},attendanceDate:date,scanTimestamp:now};}
if(identity.entity_type==='STUDENT'){if(!identity.class_id)throw Object.assign(new Error('Student has no active class assignment'),{code:'DOMAIN_VALIDATION'});const [regs]=await conn.query("SELECT id FROM attendance_registers WHERE class_id=? AND attendance_date=? AND register_type='STUDENT' LIMIT 1",[identity.class_id,date]);let registerId=regs[0]?.id;if(!registerId){registerId=newId('attreg');await conn.query('INSERT INTO attendance_registers (id,tenant_id,school_id,class_id,attendance_date,register_type,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)',[registerId,identity.tenant_id,identity.school_id,identity.class_id,date,'STUDENT',actorId||null,now,now]);}await conn.query('INSERT INTO student_attendance_records (id,register_id,student_id,status,note,recorded_by,recorded_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[newId('att'),registerId,identity.entity_id,'PRESENT','Recorded by QR attendance scan',actorId||null,now,now]);}else{const signIn=new Date().toISOString().slice(11,19);await conn.query('INSERT INTO teacher_attendance_records (id,tenant_id,school_id,staff_id,attendance_date,status,sign_in,note,recorded_by,recorded_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[newId('teacher-att'),identity.tenant_id,identity.school_id,identity.entity_id,date,'PRESENT',signIn,'Recorded by QR attendance scan',actorId||null,now,now]);}await conn.query('INSERT INTO qr_attendance_events (id,identity_id,tenant_id,school_id,entity_type,entity_id,attendance_date,scan_timestamp,attendance_method,sync_status,scan_result,scanned_by,user_agent,metadata_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[newId('qrevent'),identity.id,identity.tenant_id,identity.school_id,identity.entity_type,identity.entity_id,date,now,'QR','SYNCHRONIZED','RECORDED',actorId||null,metadata.userAgent||null,json({source:metadata.source||'camera'})]);await conn.commit();return {duplicate:false,identity:{entityType:identity.entity_type,entityId:identity.entity_id,schoolId:identity.school_id,fullName:identity.full_name},attendanceDate:date,scanTimestamp:now};}catch(e){await conn.rollback();throw e;}finally{conn.release();}}

async function hostelOverview(schoolId){await ensureInitialized();return {hostels:await domainRows('SELECT * FROM hostels WHERE school_id=? ORDER BY name',[schoolId]),blocks:await domainRows('SELECT b.*,h.name hostel_name FROM hostel_blocks b JOIN hostels h ON h.id=b.hostel_id WHERE h.school_id=? ORDER BY h.name,b.name',[schoolId]),rooms:await domainRows('SELECT r.*,b.name block_name,h.name hostel_name FROM hostel_rooms r JOIN hostel_blocks b ON b.id=r.block_id JOIN hostels h ON h.id=b.hostel_id WHERE h.school_id=? ORDER BY h.name,b.name,r.name',[schoolId]),beds:await domainRows('SELECT be.*,r.name room_name,b.name block_name,h.name hostel_name FROM hostel_beds be JOIN hostel_rooms r ON r.id=be.room_id JOIN hostel_blocks b ON b.id=r.block_id JOIN hostels h ON h.id=b.hostel_id WHERE h.school_id=? ORDER BY h.name,b.name,r.name,be.name',[schoolId]),assignments:await domainRows("SELECT a.*,s.full_name student_name,h.name hostel_name,b.name block_name,r.name room_name,be.name bed_name FROM hostel_assignments a JOIN students s ON s.id=a.student_id JOIN hostels h ON h.id=a.hostel_id LEFT JOIN hostel_blocks b ON b.id=a.block_id LEFT JOIN hostel_rooms r ON r.id=a.room_id LEFT JOIN hostel_beds be ON be.id=a.bed_id WHERE a.school_id=? AND a.status='ACTIVE' ORDER BY s.full_name",[schoolId]),rollcalls:await domainRows('SELECT rc.*,s.full_name student_name FROM hostel_roll_calls rc JOIN students s ON s.id=rc.student_id WHERE rc.school_id=? ORDER BY rc.recorded_at DESC LIMIT 100',[schoolId])};}
async function hostelCreate(input,actorId){await ensureInitialized();const now=iso(new Date()),id=newId('hostel');const conn=await getPool().getConnection();try{await conn.beginTransaction();if(input.kind==='HOSTEL')await conn.query('INSERT INTO hostels (id,tenant_id,school_id,name,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.name,input.status||'ACTIVE',actorId,now,now]);if(input.kind==='BLOCK')await conn.query('INSERT INTO hostel_blocks (id,hostel_id,name,floors,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?)',[id,input.hostelId,input.name,Number(input.floors||1),input.status||'ACTIVE',now,now]);if(input.kind==='ROOM')await conn.query('INSERT INTO hostel_rooms (id,block_id,name,capacity,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?)',[id,input.blockId,input.name,Number(input.capacity||1),input.status||'AVAILABLE',now,now]);if(input.kind==='BED')await conn.query('INSERT INTO hostel_beds (id,room_id,name,status,created_at,updated_at) VALUES (?,?,?,?,?,?)',[id,input.roomId,input.name,input.status||'AVAILABLE',now,now]);await conn.query('INSERT INTO hostel_audit_events (id,tenant_id,school_id,action,entity_type,entity_id,actor_id,payload_json,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[newId('hostel-audit'),input.tenantId,input.schoolId,'CREATE',input.kind,id,actorId,JSON.stringify(input),now]);await conn.commit();return {id};}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function hostelAssign(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();const now=iso(new Date());try{await conn.beginTransaction();const [student]=await conn.query("SELECT id,tenant_id,school_id,status FROM students WHERE id=? AND school_id=? LIMIT 1",[input.studentId,input.schoolId]);if(!student.length)throw Object.assign(new Error('Student not found in school'),{code:'DOMAIN_VALIDATION'});const [active]=await conn.query("SELECT id FROM hostel_assignments WHERE student_id=? AND status='ACTIVE' LIMIT 1",[input.studentId]);if(active.length)await conn.query("UPDATE hostel_assignments SET status='VACATED',vacated_at=?,reason=? WHERE id=?",[now,input.reason||'Reassigned',active[0].id]);if(input.bedId){const [bed]=await conn.query("SELECT be.id FROM hostel_beds be JOIN hostel_rooms r ON r.id=be.room_id JOIN hostel_blocks b ON b.id=r.block_id JOIN hostels h ON h.id=b.hostel_id WHERE be.id=? AND h.school_id=? AND be.status='AVAILABLE'",[input.bedId,input.schoolId]);if(!bed.length)throw Object.assign(new Error('Bed unavailable or outside school'),{code:'DOMAIN_VALIDATION'});}else if(input.roomId){const [count]=await conn.query("SELECT COUNT(*) n FROM hostel_assignments WHERE room_id=? AND status='ACTIVE'",[input.roomId]);const [room]=await conn.query('SELECT capacity FROM hostel_rooms WHERE id=?',[input.roomId]);if(!room.length||Number(count[0].n)>=Number(room[0].capacity))throw Object.assign(new Error('Room capacity exceeded'),{code:'DOMAIN_VALIDATION'});}const id=newId('hostel-assignment');await conn.query('INSERT INTO hostel_assignments (id,tenant_id,school_id,student_id,hostel_id,block_id,room_id,bed_id,assigned_at,status,assigned_by,reason) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[id,student[0].tenant_id,input.schoolId,input.studentId,input.hostelId,input.blockId||null,input.roomId||null,input.bedId||null,now,'ACTIVE',actorId,input.reason||null]);if(input.bedId)await conn.query("UPDATE hostel_beds SET status='OCCUPIED',updated_at=? WHERE id=?",[now,input.bedId]);await conn.query('INSERT INTO hostel_audit_events (id,tenant_id,school_id,action,entity_type,entity_id,actor_id,payload_json,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[newId('hostel-audit'),student[0].tenant_id,input.schoolId,'ASSIGN','STUDENT',input.studentId,actorId,JSON.stringify(input),now]);await conn.commit();return {id};}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function hostelRollCall(input,actorId){await ensureInitialized();const id=newId('hostel-rollcall');try{await getPool().query('INSERT INTO hostel_roll_calls (id,tenant_id,school_id,student_id,session_name,attendance_date,status,recorded_by,recorded_at,source) VALUES (?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),recorded_by=VALUES(recorded_by),recorded_at=VALUES(recorded_at),source=VALUES(source)',[id,input.tenantId,input.schoolId,input.studentId,input.sessionName||'MORNING',input.attendanceDate||new Date().toISOString().slice(0,10),input.status||'PRESENT',actorId,new Date(),input.source||'ONLINE']);return {id,ok:true};}catch(e){throw e;}}

async function transportOverview(schoolId){await ensureInitialized();return {vehicles:await domainRows("SELECT * FROM transport_vehicles WHERE school_id=? ORDER BY name",[schoolId]),routes:await domainRows("SELECT r.*,COUNT(s.id) stop_count FROM transport_routes r LEFT JOIN transport_stops s ON s.route_id=r.id AND s.active=TRUE WHERE r.school_id=? GROUP BY r.id ORDER BY r.name",[schoolId]),stops:await domainRows("SELECT s.* FROM transport_stops s JOIN transport_routes r ON r.id=s.route_id WHERE r.school_id=? ORDER BY s.route_id,s.stop_order",[schoolId]),assignments:await domainRows("SELECT a.*,st.full_name student_name,r.name route_name,v.name vehicle_name,ts.name stop_name FROM transport_student_assignments a JOIN students st ON st.id=a.student_id JOIN transport_routes r ON r.id=a.route_id LEFT JOIN transport_vehicles v ON v.id=a.vehicle_id LEFT JOIN transport_stops ts ON ts.id=a.stop_id WHERE a.school_id=? AND a.status='ACTIVE' ORDER BY st.full_name",[schoolId]),events:await domainRows("SELECT e.*,st.full_name student_name,r.name route_name,v.name vehicle_name FROM transport_events e JOIN students st ON st.id=e.student_id LEFT JOIN transport_routes r ON r.id=e.route_id LEFT JOIN transport_vehicles v ON v.id=e.vehicle_id WHERE e.school_id=? AND e.event_date=CURDATE() ORDER BY e.event_time DESC",[schoolId]),locations:await domainRows("SELECT l.* FROM transport_locations l JOIN (SELECT vehicle_id,MAX(recorded_at) t FROM transport_locations WHERE school_id=? GROUP BY vehicle_id) x ON x.vehicle_id=l.vehicle_id AND x.t=l.recorded_at WHERE l.school_id=?",[schoolId,schoolId])};}
async function transportCreate(input,actorId){await ensureInitialized();const now=iso(new Date()),id=newId('transport');if(input.kind==='VEHICLE')await getPool().query("INSERT INTO transport_vehicles (id,tenant_id,school_id,registration_no,name,capacity,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)",[id,input.tenantId,input.schoolId,input.registrationNo,input.name,Number(input.capacity||1),input.status||'ACTIVE',actorId,now,now]);else if(input.kind==='ROUTE')await getPool().query("INSERT INTO transport_routes (id,tenant_id,school_id,name,description,route_type,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",[id,input.tenantId,input.schoolId,input.name,input.description||null,input.routeType||'BOTH',input.status||'ACTIVE',actorId,now,now]);else {const [r]=await getPool().query("SELECT id FROM transport_routes WHERE id=? AND school_id=? AND tenant_id=?",[input.routeId,input.schoolId,input.tenantId]);if(!r.length)throw Object.assign(new Error('Route outside school'),{code:'DOMAIN_VALIDATION'});await getPool().query("INSERT INTO transport_stops (id,route_id,name,stop_order) VALUES (?,?,?,?)",[id,input.routeId,input.name,Number(input.stopOrder||1)]);}await getPool().query("INSERT INTO transport_audit_events (id,tenant_id,school_id,action,entity_type,entity_id,actor_id,payload_json,created_at) VALUES (?,?,?,?,?,?,?,?,?)",[newId('transport-audit'),input.tenantId,input.schoolId,'CREATE',input.kind,id,actorId,JSON.stringify(input),now]);return {id};}
async function transportAssign(input,actorId){await ensureInitialized();const conn=await getPool().getConnection();const now=iso(new Date());try{await conn.beginTransaction();const [s]=await conn.query("SELECT id,tenant_id FROM students WHERE id=? AND school_id=? AND tenant_id=? AND status='ACTIVE'",[input.studentId,input.schoolId,input.tenantId]);const [r]=await conn.query("SELECT id FROM transport_routes WHERE id=? AND school_id=? AND tenant_id=? AND status='ACTIVE'",[input.routeId,input.schoolId,input.tenantId]);if(!s.length||!r.length)throw Object.assign(new Error('Student or route is outside the authorized school'),{code:'DOMAIN_VALIDATION'});await conn.query("UPDATE transport_student_assignments SET status='INACTIVE',effective_to=? WHERE student_id=? AND school_id=? AND status='ACTIVE'",[now.slice(0,10),input.studentId,input.schoolId]);const id=newId('transport-assignment');await conn.query("INSERT INTO transport_student_assignments (id,tenant_id,school_id,student_id,route_id,stop_id,vehicle_id,effective_from,status,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)",[id,input.tenantId,input.schoolId,input.studentId,input.routeId,input.stopId||null,input.vehicleId||null,input.effectiveFrom||now.slice(0,10),'ACTIVE',actorId]);await conn.query("INSERT INTO transport_audit_events (id,tenant_id,school_id,action,entity_type,entity_id,actor_id,payload_json,created_at) VALUES (?,?,?,?,?,?,?,?,?)",[newId('transport-audit'),input.tenantId,input.schoolId,'ASSIGN','STUDENT',input.studentId,actorId,JSON.stringify(input),now]);await conn.commit();return {id};}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
async function transportEvent(input,actorId){await ensureInitialized();const date=input.eventDate||new Date().toISOString().slice(0,10),status=String(input.eventStatus||'PICKED_UP').toUpperCase();if(!['PICKED_UP','NOT_PICKED_UP','DROPPED_OFF','NOT_DROPPED_OFF','DELAYED','CANCELLED'].includes(status))throw Object.assign(new Error('Invalid transport event status'),{code:'DOMAIN_VALIDATION'});const [a]=await getPool().query("SELECT id,route_id,vehicle_id FROM transport_student_assignments WHERE student_id=? AND school_id=? AND tenant_id=? AND status='ACTIVE' LIMIT 1",[input.studentId,input.schoolId,input.tenantId]);if(!a.length)throw Object.assign(new Error('Student has no active transport assignment'),{code:'DOMAIN_VALIDATION'});const id=newId('transport-event');await getPool().query("INSERT INTO transport_events (id,tenant_id,school_id,student_id,route_id,vehicle_id,event_date,event_time,event_status,source,recorded_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",[id,input.tenantId,input.schoolId,input.studentId,input.routeId||a[0].route_id,input.vehicleId||a[0].vehicle_id,date,new Date(),status,input.source||'MANUAL',actorId,new Date()]);return {id,ok:true};}
async function transportLocation(input,actorId){await ensureInitialized();const [v]=await getPool().query("SELECT id FROM transport_vehicles WHERE id=? AND school_id=? AND tenant_id=? AND status='ACTIVE'",[input.vehicleId,input.schoolId,input.tenantId]);if(!v.length)throw Object.assign(new Error('Vehicle outside authorized school'),{code:'DOMAIN_VALIDATION'});const id=newId('transport-location');await getPool().query("INSERT INTO transport_locations (id,tenant_id,school_id,vehicle_id,latitude,longitude,recorded_at,source,recorded_by) VALUES (?,?,?,?,?,?,?,?,?)",[id,input.tenantId,input.schoolId,input.vehicleId,Number(input.latitude),Number(input.longitude),new Date(),input.source||'SIMULATION',actorId]);return {id,ok:true};}
async function transportParentView(userId){await ensureInitialized();return domainRows("SELECT a.student_id,st.full_name student_name,r.name route_name,ts.name stop_name,v.name vehicle_name,MAX(CASE WHEN e.event_status='PICKED_UP' THEN e.event_time END) pickup_time,MAX(CASE WHEN e.event_status='DROPPED_OFF' THEN e.event_time END) dropoff_time FROM parent_student_relationships p JOIN students st ON st.id=p.student_id JOIN transport_student_assignments a ON a.student_id=st.id AND a.status='ACTIVE' JOIN transport_routes r ON r.id=a.route_id LEFT JOIN transport_stops ts ON ts.id=a.stop_id LEFT JOIN transport_vehicles v ON v.id=a.vehicle_id LEFT JOIN transport_events e ON e.student_id=st.id AND e.event_date=CURDATE() WHERE p.parent_user_id=? AND p.active=TRUE GROUP BY a.student_id,st.full_name,r.name,ts.name,v.name",[userId]);}

async function transportStaffAssign(input,actorId){await ensureInitialized();const [v]=await getPool().query("SELECT id FROM transport_vehicles WHERE id=? AND school_id=? AND tenant_id=?",[input.vehicleId,input.schoolId,input.tenantId]);const [st]=await getPool().query("SELECT id FROM staff WHERE id=? AND school_id=? AND tenant_id=? AND status='ACTIVE'",[input.staffId,input.schoolId,input.tenantId]);if(!v.length||!st.length)throw Object.assign(new Error('Vehicle or staff member is outside the authorized school'),{code:'DOMAIN_VALIDATION'});const id=newId('transport-staff');const now=iso(new Date());await getPool().query("UPDATE transport_staff_assignments SET status='INACTIVE',effective_to=? WHERE vehicle_id=? AND staff_role=? AND status='ACTIVE'",[now.slice(0,10),input.vehicleId,input.staffRole||'DRIVER']);await getPool().query("INSERT INTO transport_staff_assignments (id,tenant_id,school_id,vehicle_id,staff_id,staff_role,effective_from,status,created_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",[id,input.tenantId,input.schoolId,input.vehicleId,input.staffId,input.staffRole||'DRIVER',input.effectiveFrom||now.slice(0,10),'ACTIVE',actorId,now]);return {id};}

async function submitPendingAdmission(input){await ensureInitialized();const type=String(input.admissionType||'').toUpperCase();if(!['NEW','TRANSFER'].includes(type))throw Object.assign(new Error('Invalid admission type'),{code:'DOMAIN_VALIDATION'});const required=['regionId','districtId','schoolId','level','classId','applicant','guardian'];for(const k of required)if(!input[k])throw Object.assign(new Error('Missing required application information'),{code:'DOMAIN_VALIDATION'});const [valid]=await getPool().query("SELECT s.id school_id,s.tenant_id,d.id district_id,r.id region_id,c.id class_id,c.name class_name FROM schools s JOIN districts d ON d.id=s.district_id JOIN regions r ON r.id=d.region_id JOIN classes c ON c.school_id=s.id WHERE s.id=? AND s.active=TRUE AND d.id=? AND r.id=? AND c.id=? AND c.status='ACTIVE' LIMIT 1",[input.schoolId,input.districtId,input.regionId,input.classId]);if(!valid.length)throw Object.assign(new Error('Selected school, district, region, or class is not valid'),{code:'DOMAIN_VALIDATION'});const phone=String(input.guardian.phone||'').replace(/[\\s()-]/g,'');if(!/^\\+?[0-9]{7,15}$/.test(phone))throw Object.assign(new Error('Enter a valid guardian phone number'),{code:'DOMAIN_VALIDATION'});if(input.guardian.email&& !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(String(input.guardian.email)))throw Object.assign(new Error('Enter a valid guardian email'),{code:'DOMAIN_VALIDATION'});const applicantHash=crypto.createHash('sha256').update(JSON.stringify({name:input.applicant.name,dob:input.applicant.dateOfBirth,phone,school:input.schoolId,type})).digest('hex');const [dup]=await getPool().query("SELECT application_reference FROM pending_admission_applications WHERE school_id=? AND applicant_hash=? AND status='PENDING_REVIEW' LIMIT 1",[input.schoolId,applicantHash]);if(dup.length)throw Object.assign(new Error('A similar pending application already exists for this school'),{code:'DUPLICATE_APPLICATION'});const id=newId('admission');const ref='ADM-'+new Date().getUTCFullYear()+'-'+crypto.randomBytes(5).toString('hex').toUpperCase();const now=iso(new Date());await getPool().query("INSERT INTO pending_admission_applications (id,application_reference,admission_type,tenant_id,region_id,district_id,school_id,level,class_id,applicant_json,guardian_json,documents_json,status,submitted_at,created_at,updated_at,applicant_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[id,ref,type,valid[0].tenant_id,valid[0].region_id,valid[0].district_id,valid[0].school_id,input.level,valid[0].class_id,JSON.stringify(input.applicant),JSON.stringify(input.guardian),JSON.stringify(input.documents||[]),'PENDING_REVIEW',now,now,now,applicantHash]);return {applicationReference:ref,status:'PENDING_REVIEW',admissionType:type,schoolId:valid[0].school_id,classId:valid[0].class_id,level:input.level,submittedAt:now};}

async function listPendingAdmissions(schoolId,filters={}){await ensureInitialized();let sql='SELECT p.id,p.application_reference,p.admission_type,p.region_id,p.district_id,p.school_id,p.level,p.class_id,p.applicant_json,p.guardian_json,p.documents_json,p.status,p.submitted_at,p.review_reason,p.student_id,p.permanent_student_id,c.name class_name FROM pending_admission_applications p LEFT JOIN classes c ON c.id=p.class_id WHERE p.school_id=?';const vals=[schoolId];if(filters.status){sql+=' AND p.status=?';vals.push(filters.status)}if(filters.type){sql+=' AND p.admission_type=?';vals.push(filters.type)}if(filters.q){sql+=' AND (p.application_reference LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(p.applicant_json,\'$.name\')) LIKE ?)';vals.push('%'+filters.q+'%','%'+filters.q+'%')}sql+=' ORDER BY p.submitted_at DESC LIMIT 200';const [rows]=await getPool().query(sql,vals);return rows.map(r=>({...r,applicant:parseJson(r.applicant_json),guardian:parseJson(r.guardian_json),documents:parseJson(r.documents_json)||[]}))}
async function getPendingAdmission(id,schoolId){await ensureInitialized();const [rows]=await getPool().query('SELECT p.*,c.name class_name,s.name school_name,d.name district_name,r.name region_name FROM pending_admission_applications p LEFT JOIN classes c ON c.id=p.class_id LEFT JOIN schools s ON s.id=p.school_id LEFT JOIN districts d ON d.id=p.district_id LEFT JOIN regions r ON r.id=p.region_id WHERE p.id=? AND p.school_id=? LIMIT 1',[id,schoolId]);if(!rows.length)return null;const r=rows[0];r.applicant=parseJson(r.applicant_json);r.guardian=parseJson(r.guardian_json);r.documents=parseJson(r.documents_json)||[];const [history]=await getPool().query('SELECT action,from_status,to_status,reason,actor_user_id,created_at FROM admission_review_history WHERE application_id=? ORDER BY created_at ASC',[id]);r.history=history;return r}
async function transitionPendingAdmission(id,schoolId,action,reason,actorUserId){await ensureInitialized();const conn=await getPool().getConnection();const transitions={START_REVIEW:{from:['PENDING_REVIEW','RESUBMITTED'],to:'UNDER_REVIEW',need:false},REQUEST_CORRECTION:{from:['UNDER_REVIEW'],to:'CORRECTION_REQUIRED',need:true},REJECT:{from:['UNDER_REVIEW'],to:'REJECTED',need:true},APPROVE:{from:['UNDER_REVIEW'],to:'APPROVED',need:false},RESUBMIT:{from:['CORRECTION_REQUIRED'],to:'RESUBMITTED',need:false}};const rule=transitions[action];if(!rule)throw Object.assign(new Error('Unsupported admission action'),{code:'DOMAIN_VALIDATION'});try{await conn.beginTransaction();const [rows]=await conn.query('SELECT id,status FROM pending_admission_applications WHERE id=? AND school_id=? FOR UPDATE',[id,schoolId]);if(!rows.length)throw Object.assign(new Error('Application not found'),{code:'NOT_FOUND'});if(!rule.from.includes(rows[0].status))throw Object.assign(new Error('Invalid admission status transition'),{code:'DOMAIN_VALIDATION'});if(rule.need&&!String(reason||'').trim())throw Object.assign(new Error('A reason is required for this action'),{code:'DOMAIN_VALIDATION'});const now=iso(new Date());await conn.query('UPDATE pending_admission_applications SET status=?,review_reason=?,reviewed_by=?,updated_at=? WHERE id=? AND school_id=?',[rule.to,reason||null,actorUserId,now,id,schoolId]);await conn.query('INSERT INTO admission_review_history (id,application_id,school_id,actor_user_id,action,from_status,to_status,reason,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[newId('admission_review'),id,schoolId,actorUserId,action,rows[0].status,rule.to,reason||null,now]);await conn.commit();return {id,status:rule.to}}catch(e){await conn.rollback();throw e}finally{conn.release()}}
async function finalizePendingAdmission(id,schoolId,actorUserId){await ensureInitialized();const conn=await getPool().getConnection();try{await conn.beginTransaction();const [rows]=await conn.query('SELECT p.*,c.name class_name FROM pending_admission_applications p JOIN classes c ON c.id=p.class_id AND c.school_id=p.school_id AND c.status=\'ACTIVE\' WHERE p.id=? AND p.school_id=? FOR UPDATE',[id,schoolId]);if(!rows.length)throw Object.assign(new Error('Application not found'),{code:'NOT_FOUND'});const a=rows[0];if(a.status==='ADMITTED'&&a.student_id)return {status:'ADMITTED',studentId:a.student_id,permanentStudentId:a.permanent_student_id,applicationReference:a.application_reference};if(a.status!=='APPROVED')throw Object.assign(new Error('Only approved applications can be finalized'),{code:'DOMAIN_VALIDATION'});const applicant=parseJson(a.applicant_json)||{};const guardian=parseJson(a.guardian_json)||{};const studentId=newId('student');const permanent='GES-'+String(a.school_id).slice(-8)+'-'+crypto.randomBytes(4).toString('hex').toUpperCase();const now=iso(new Date());const fullName=String(applicant.name||'').trim();if(!fullName)throw Object.assign(new Error('Applicant name is required'),{code:'DOMAIN_VALIDATION'});await conn.query('INSERT INTO students (id,admission_number,student_identifier,full_name,date_of_birth,gender,tenant_id,school_id,class_id,admission_date,special_needs,emergency_contact,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[studentId,a.application_reference,permanent,fullName,applicant.dateOfBirth||null,applicant.gender||null,a.tenant_id,a.school_id,a.class_id,new Date(),null,guardian.phone||null,'ACTIVE',now,now]);await conn.query('UPDATE pending_admission_applications SET status=\'ADMITTED\',student_id=?,permanent_student_id=?,reviewed_by=?,updated_at=? WHERE id=? AND school_id=?',[studentId,permanent,actorUserId,now,id,schoolId]);await conn.query('INSERT INTO admission_review_history (id,application_id,school_id,actor_user_id,action,from_status,to_status,reason,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[newId('admission_review'),id,schoolId,actorUserId,'FINALIZE_ADMISSION','APPROVED','ADMITTED',null,now]);await conn.commit();return {status:'ADMITTED',studentId,permanentStudentId:permanent,applicationReference:a.application_reference,fullName}}catch(e){await conn.rollback();throw e}finally{conn.release()}}

async function resolveCommunicationAudience(audience,scope={}){await ensureInitialized();const kind=String(audience.kind||'ALL_PARENTS').toUpperCase();let sql='SELECT DISTINCT u.id user_id,u.email,s.id student_id FROM users u LEFT JOIN parent_student_relationships ps ON ps.parent_user_id=u.id AND ps.active=TRUE LEFT JOIN students s ON s.id=ps.student_id WHERE u.active=TRUE';const vals=[];if(kind==='ALL_PARENTS'||kind==='PARENTS_CLASS'){sql+=' AND EXISTS (SELECT 1 FROM parent_student_relationships px JOIN students sx ON sx.id=px.student_id WHERE px.parent_user_id=u.id AND px.active=TRUE';if(scope.schoolId){sql+=' AND sx.school_id=?';vals.push(scope.schoolId)}if(audience.classId){sql+=' AND sx.class_id=?';vals.push(audience.classId)}sql+=')'}else if(kind==='ALL_STUDENTS'||kind==='STUDENTS_CLASS'){sql='SELECT DISTINCT u.id user_id,u.email,s.id student_id FROM users u JOIN students s ON s.student_identifier=u.email WHERE u.active=TRUE';if(scope.schoolId){sql+=' AND s.school_id=?';vals.push(scope.schoolId)}if(audience.classId){sql+=' AND s.class_id=?';vals.push(audience.classId)}}else{sql+=' AND 1=0'}const [rows]=await getPool().query(sql,vals);return rows.filter(r=>r.email).map(r=>({userId:r.user_id,studentId:r.student_id,destination:r.email}))}
async function createCommunicationCampaign(input,actorUserId,scope={}){await ensureInitialized();const channel=String(input.channel||'SMS').toUpperCase();if(!['SMS','EMAIL','PUSH'].includes(channel))throw Object.assign(new Error('Unsupported communication channel'),{code:'DOMAIN_VALIDATION'});if(channel==='PUSH')throw Object.assign(new Error('Push notification infrastructure is not configured'),{code:'DOMAIN_VALIDATION'});if(!String(input.message||'').trim())throw Object.assign(new Error('Message body is required'),{code:'DOMAIN_VALIDATION'});const recipients=await resolveCommunicationAudience(input.audience||{},scope);if(!recipients.length)throw Object.assign(new Error('No authorized recipients match this audience'),{code:'DOMAIN_VALIDATION'});const id=newId('campaign'),now=iso(new Date()),schedule=input.scheduleAt?iso(input.scheduleAt):null,status=schedule?'SCHEDULED':'PROCESSING';const conn=await getPool().getConnection();try{await conn.beginTransaction();await conn.query('INSERT INTO communication_campaigns (id,tenant_id,scope_json,name,channel,subject,message,audience_json,recipient_count,schedule_at,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[id,scope.tenantId||null,json(scope),input.name||null,channel,input.subject||null,String(input.message).trim(),json(input.audience||{}),recipients.length,schedule,status,actorUserId,now,now]);for(const r of recipients)await conn.query('INSERT INTO communication_campaign_recipients (id,campaign_id,recipient_user_id,recipient_student_id,destination,status,created_at) VALUES (?,?,?,?,?,?,?)',[newId('campaign_recipient'),id,r.userId,r.studentId,r.destination,schedule?'PENDING':'SENT',now]);if(!schedule){await conn.query('UPDATE communication_campaigns SET status=\'SENT\',sent_at=?,updated_at=? WHERE id=?',[now,now,id])}await conn.commit();return {id,recipientCount:recipients.length,status:schedule?'SCHEDULED':'SENT',delivered:0,sent:schedule?0:recipients.length,pending:schedule?recipients.length:0}}catch(e){await conn.rollback();throw e}finally{conn.release()}}
async function listCommunicationCampaigns(scope={}){await ensureInitialized();const [rows]=await getPool().query('SELECT id,name,channel,audience_json,recipient_count,schedule_at,status,created_by,created_at,sent_at FROM communication_campaigns WHERE (tenant_id=? OR tenant_id IS NULL) ORDER BY created_at DESC LIMIT 200',[scope.tenantId||'']);return rows.map(r=>({...r,audience:parseJson(r.audience_json)}))}
async function getCommunicationCampaign(id,scope={}){await ensureInitialized();const [rows]=await getPool().query('SELECT * FROM communication_campaigns WHERE id=? AND (tenant_id=? OR tenant_id IS NULL)',[id,scope.tenantId||'']);if(!rows.length)return null;const r=rows[0];r.audience=parseJson(r.audience_json);const [d]=await getPool().query('SELECT status,COUNT(*) count FROM communication_campaign_recipients WHERE campaign_id=? GROUP BY status',[id]);r.delivery=d;return r}

async function chatContacts(userId,role,schoolId){await ensureInitialized();const r=String(role||'').toUpperCase();let sql='';const vals=[userId,schoolId];if(r==='PARENT'){sql='SELECT DISTINCT u.id user_id,COALESCE(st.full_name,u.email) display_name,\'TEACHER\' role FROM users u JOIN staff st ON st.user_id=u.id JOIN user_roles ur ON ur.user_id=u.id JOIN roles ro ON ro.id=ur.role_id AND ro.name=\'TEACHER\' JOIN teacher_class_assignments tca ON tca.staff_id=st.id AND tca.active=TRUE JOIN students s ON s.class_id=tca.class_id AND s.school_id=? JOIN parent_student_relationships ps ON ps.student_id=s.id AND ps.parent_user_id=? AND ps.active=TRUE WHERE u.active=TRUE UNION SELECT DISTINCT u.id,COALESCE(st.full_name,u.email),\'HEADTEACHER\' FROM users u JOIN staff st ON st.user_id=u.id JOIN user_roles ur ON ur.user_id=u.id JOIN roles ro ON ro.id=ur.role_id AND ro.name=\'HEADTEACHER\' JOIN staff_school_assignments ssa ON ssa.staff_id=st.id AND ssa.school_id=? AND ssa.active=TRUE WHERE u.active=TRUE';return (await getPool().query(sql,[schoolId,userId,schoolId]))[0]}if(r==='TEACHER'){sql='SELECT DISTINCT u.id user_id,COALESCE(u.email,st.full_name) display_name,\'PARENT\' role FROM users u JOIN parent_student_relationships ps ON ps.parent_user_id=u.id AND ps.active=TRUE JOIN students s ON s.id=ps.student_id AND s.school_id=? JOIN teacher_class_assignments tca ON tca.class_id=s.class_id AND tca.active=TRUE JOIN staff ts ON ts.id=tca.staff_id AND ts.user_id=? WHERE u.active=TRUE';return (await getPool().query(sql,[schoolId,userId]))[0]}sql='SELECT DISTINCT u.id user_id,COALESCE(st.full_name,u.email) display_name,\'PARENT\' role FROM users u JOIN parent_student_relationships ps ON ps.parent_user_id=u.id AND ps.active=TRUE JOIN students s ON s.id=ps.student_id AND s.school_id=? JOIN staff st ON st.user_id=? WHERE u.active=TRUE';return (await getPool().query(sql,[schoolId,userId]))[0]}
async function chatConversation(userId,otherUserId,schoolId,role){await ensureInitialized();const contacts=await chatContacts(userId,role,schoolId);if(!contacts.some(x=>String(x.user_id)===String(otherUserId)))throw Object.assign(new Error('Chat relationship is not authorized'),{code:'FORBIDDEN'});const a=String(userId)<String(otherUserId)?userId:otherUserId,b=String(userId)<String(otherUserId)?otherUserId:userId;const conn=await getPool().getConnection();try{await conn.beginTransaction();let [rows]=await conn.query('SELECT * FROM chat_conversations WHERE school_id=? AND participant_a=? AND participant_b=? FOR UPDATE',[schoolId,a,b]);let row=rows[0];if(!row){const now=iso(new Date());const id=newId('chat');await conn.query('INSERT INTO chat_conversations (id,school_id,tenant_id,participant_a,participant_b,created_at) VALUES (?,?,?,?,?,?)',[id,schoolId,null,a,b,now]);row={id,school_id:schoolId,participant_a:a,participant_b:b,created_at:now}}await conn.commit();return row}catch(e){await conn.rollback();throw e}finally{conn.release()}}
async function chatConversations(userId,schoolId,role){await ensureInitialized();const contacts=await chatContacts(userId,role,schoolId);const ids=contacts.map(x=>x.user_id);if(!ids.length)return [];const [rows]=await getPool().query('SELECT c.*,CASE WHEN c.participant_a=? THEN c.participant_b ELSE c.participant_a END other_user_id,MAX(m.sent_at) last_message_at,SUM(CASE WHEN m.recipient_id=? AND m.read_at IS NULL THEN 1 ELSE 0 END) unread_count FROM chat_conversations c LEFT JOIN chat_messages m ON m.conversation_id=c.id WHERE c.school_id=? AND (c.participant_a=? OR c.participant_b=?) GROUP BY c.id ORDER BY last_message_at DESC',[userId,userId,schoolId,userId,userId]);return rows.filter(x=>ids.includes(x.other_user_id))}
async function chatMessages(conversationId,userId,schoolId,limit=50,before){await ensureInitialized();const [c]=await getPool().query('SELECT id FROM chat_conversations WHERE id=? AND school_id=? AND (participant_a=? OR participant_b=?)',[conversationId,schoolId,userId]);if(!c.length)throw Object.assign(new Error('Conversation not found'),{code:'NOT_FOUND'});let sql='SELECT id,sender_id,recipient_id,body,status,sent_at,delivered_at,read_at FROM chat_messages WHERE conversation_id=?';const vals=[conversationId];if(before){sql+=' AND sent_at<?';vals.push(before)}sql+=' ORDER BY sent_at DESC LIMIT ?';vals.push(Math.min(Math.max(Number(limit)||50,1),100));const [rows]=await getPool().query(sql,vals);await getPool().query('UPDATE chat_messages SET read_at=NOW(),status=\'READ\' WHERE conversation_id=? AND recipient_id=? AND read_at IS NULL',[conversationId,userId]);return rows.reverse()}
async function sendChatMessage(conversationId,userId,schoolId,role,body,nonce){await ensureInitialized();const [c]=await getPool().query('SELECT * FROM chat_conversations WHERE id=? AND school_id=? AND (participant_a=? OR participant_b=?)',[conversationId,schoolId,userId]);if(!c.length)throw Object.assign(new Error('Conversation not found'),{code:'NOT_FOUND'});const other=c[0].participant_a===userId?c[0].participant_b:c[0].participant_a;const contacts=await chatContacts(userId,role,schoolId);if(!contacts.some(x=>String(x.user_id)===String(other)))throw Object.assign(new Error('Chat relationship is not authorized'),{code:'FORBIDDEN'});const text=String(body||'').trim();if(!text||text.length>4000)throw Object.assign(new Error('Message must be between 1 and 4000 characters'),{code:'DOMAIN_VALIDATION'});const id=newId('chat_message'),now=iso(new Date());try{await getPool().query('INSERT INTO chat_messages (id,conversation_id,sender_id,recipient_id,body,status,sent_at,client_nonce) VALUES (?,?,?,?,?,?,?,?)',[id,conversationId,userId,other,text,'SENT',now,nonce||id]);await getPool().query('UPDATE chat_conversations SET last_message_at=? WHERE id=?',[now,conversationId])}catch(e){if(e.code==='ER_DUP_ENTRY'){const [rows]=await getPool().query('SELECT * FROM chat_messages WHERE conversation_id=? AND sender_id=? AND client_nonce=?',[conversationId,userId,nonce]);return rows[0]}throw e}return {id,conversationId,senderId:userId,recipientId:other,body:text,status:'SENT',sentAt:now}}

async function multiSchoolSummary(scope={}){await ensureInitialized();const role=String(scope.role||'').toUpperCase();let where='s.active=TRUE';const vals=[];if(role==='DISTRICT_ADMIN'){const ids=(scope.districtIds||[]).map(String);if(!ids.length)return {scope:'district',totals:{schools:0,students:0,boys:0,girls:0,specialNeeds:0,teachers:0,pendingAdmissions:0},schools:[]};where+=' AND s.district_id IN ('+ids.map(()=>'?').join(',')+')';vals.push(...ids)}else if(role==='REGIONAL_ADMIN'){const ids=(scope.regionIds||[]).map(String);if(!ids.length)return {scope:'region',totals:{schools:0,students:0,boys:0,girls:0,specialNeeds:0,teachers:0,pendingAdmissions:0},schools:[]};where+=' AND d.region_id IN ('+ids.map(()=>'?').join(',')+')';vals.push(...ids)}else if(!['NATIONAL_ADMIN','SUPER_ADMIN','DEVELOPER_ROOT'].includes(role)){return {scope:'none',totals:{schools:0,students:0,boys:0,girls:0,specialNeeds:0,teachers:0,pendingAdmissions:0},schools:[]}}if(scope.filters?.schoolId){where+=' AND s.id=?';vals.push(scope.filters.schoolId)}if(scope.filters?.districtId&&role==='REGIONAL_ADMIN'){where+=' AND s.district_id=?';vals.push(scope.filters.districtId)}if(scope.filters?.search){where+=' AND s.name LIKE ?';vals.push('%'+scope.filters.search+'%')}const sql=`SELECT s.id school_id,s.name school_name,s.district_id,d.name district_name,r.id region_id,r.name region_name,COUNT(DISTINCT st.id) students,COUNT(DISTINCT CASE WHEN LOWER(COALESCE(st.gender,'')) IN ('male','m','boy','boys') THEN st.id END) boys,COUNT(DISTINCT CASE WHEN LOWER(COALESCE(st.gender,'')) IN ('female','f','girl','girls') THEN st.id END) girls,COUNT(DISTINCT CASE WHEN st.special_needs IS NOT NULL AND st.special_needs<>'' THEN st.id END) special_needs,COUNT(DISTINCT CASE WHEN sf.status='ACTIVE' THEN sf.id END) teachers,COUNT(DISTINCT CASE WHEN pa.status IN ('PENDING_REVIEW','UNDER_REVIEW','CORRECTION_REQUIRED','RESUBMITTED') THEN pa.id END) pending_admissions FROM schools s JOIN districts d ON d.id=s.district_id JOIN regions r ON r.id=d.region_id LEFT JOIN students st ON st.school_id=s.id AND st.status='ACTIVE' LEFT JOIN staff sf ON sf.school_id=s.id LEFT JOIN pending_admission_applications pa ON pa.school_id=s.id WHERE ${where} GROUP BY s.id,s.name,s.district_id,d.name,r.id,r.name ORDER BY s.name`;const [rows]=await getPool().query(sql,vals);const totals=rows.reduce((a,x)=>{a.schools++;a.students+=Number(x.students||0);a.boys+=Number(x.boys||0);a.girls+=Number(x.girls||0);a.specialNeeds+=Number(x.special_needs||0);a.teachers+=Number(x.teachers||0);a.pendingAdmissions+=Number(x.pending_admissions||0);return a},{schools:0,students:0,boys:0,girls:0,specialNeeds:0,teachers:0,pendingAdmissions:0});return {scope:role==='DISTRICT_ADMIN'?'district':role==='REGIONAL_ADMIN'?'region':'national',totals,schools:rows.map(x=>({schoolId:x.school_id,school:x.school_name,districtId:x.district_id,district:x.district_name,regionId:x.region_id,region:x.region_name,students:Number(x.students||0),boys:Number(x.boys||0),girls:Number(x.girls||0),specialNeeds:Number(x.special_needs||0),teachers:Number(x.teachers||0),pendingAdmissions:Number(x.pending_admissions||0)}))}}
async function getOrganizationBranding(scopeType,scopeId){await ensureInitialized();const [rows]=await getPool().query('SELECT scope_type,scope_id,display_name,logo_url,primary_color,accent_color,updated_at FROM organization_branding WHERE scope_type=? AND scope_id=?',[scopeType,scopeId]);return rows[0]||null}
async function setOrganizationBranding(input,actorId){await ensureInitialized();const now=iso(new Date());await getPool().query('INSERT INTO organization_branding (scope_type,scope_id,tenant_id,display_name,logo_url,primary_color,accent_color,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),logo_url=VALUES(logo_url),primary_color=VALUES(primary_color),accent_color=VALUES(accent_color),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)',[input.scopeType,input.scopeId,input.tenantId||null,input.displayName||null,input.logoUrl||null,input.primaryColor||null,input.accentColor||null,actorId,now]);return getOrganizationBranding(input.scopeType,input.scopeId)}

